$$
\begin{align*}
& =1+n(k x)+\frac{n(n-1)(k x)^{2}}{2}+\cdots \\
& =1+n k x+\frac{n(n-1) k^{2}}{2} x^{2}+\cdots  \tag{$1 \mathrm{M}+1 \mathrm{~A}$}\\
